head.b:skin:
/* 
THEME: Islamic Preacher Framework (Navy & Gold Edition)
SYSTEM: Khutbah & Da'wah Script Engine
*/
:root {
    --navy: #0f172a;
    --gold: #c5a059;
    --soft-gold: #f4ecd8;
    --white: #ffffff;
    --text-gray: #475569;
}
body {
    background-color: #f1f5f9;
    color: var(--navy);
    font-family: 'Amiri', 'Inter', serif;
    margin: 0; padding: 0;
}
.header-wrap {
    background: linear-gradient(135deg, var(--navy), #1e293b);
    color: var(--gold);
    padding: 50px 20px;
    text-align: center;
    border-bottom: 4px solid var(--gold);
}
.main-container {
    max-width: 850px;
    margin: -30px auto 60px;
    padding: 20px;
}
.daawah-card {
    background: var(--white);
    border-radius: 15px;
    box-shadow: 0 10px 30px rgba(15, 23, 42, 0.1);
    padding: 40px;
    margin-bottom: 25px;
    border: 1px solid var(--soft-gold);
    border-top: 6px solid var(--gold);
}
.input-group { margin-bottom: 25px; }
.input-group label {
    display: block;
    font-weight: bold;
    margin-bottom: 8px;
    color: var(--navy);
    font-size: 14px;
    text-transform: uppercase;
    letter-spacing: 1px;
}
.input-group input, .input-group textarea {
    width: 100%;
    padding: 15px;
    border: 1px solid #e2e8f0;
    border-radius: 8px;
    font-family: 'Inter', sans-serif;
    box-sizing: border-box;
    background: #fff;
    font-size: 15px;
}
.input-group textarea { height: 110px; resize: vertical; }

.lang-options { display: flex; gap: 30px; margin-top: 10px; }
.lang-item { display: flex; align-items: center; cursor: pointer; font-weight: 600; }
.lang-item input { width: auto; margin-right: 10px; accent-color: var(--gold); }

h2 { color: var(--navy); text-align: center; margin-top: 0; font-size: 26px; border-bottom: 1px solid var(--soft-gold); padding-bottom: 15px; }

.copy-btn {
    background: var(--gold);
    color: var(--navy);
    border: none;
    padding: 18px;
    cursor: pointer;
    font-weight: bold;
    width: 100%;
    border-radius: 8px;
    transition: 0.3s;
    font-size: 15px;
    text-transform: uppercase;
    letter-spacing: 1px;
}
.copy-btn:hover { background: var(--navy); color: var(--gold); }
footer { text-align: center; color: var(--text-gray); padding: 20px; font-size: 13px; }

body.script:
function copyPrompt() {
    var title = document.getElementById("inputTitle").value || "[Tema Belum Diisi]";
    var notes = document.getElementById("inputNotes").value || "[Tanpa Catatan Tambahan]";

    var selectedLang = document.querySelector('input[name="lang"]:checked').value;
    var template = (selectedLang === 'id') ? 
                   document.getElementById("templateID").innerText : 
                   document.getElementById("templateAR").innerText;

    var finalPrompt = template.replace("[USER_TITLE]", title).replace("[USER_NOTES]", notes);

    var tempElem = document.createElement("textarea");
    tempElem.value = finalPrompt;
    document.body.appendChild(tempElem);
    tempElem.select();
    document.execCommand("copy");
    document.body.removeChild(tempElem);

    alert("✨ Prompt Khotbah (" + (selectedLang === 'id' ? 'Indonesia' : 'Arab') + ") Berhasil Disalin!");
}
